import{_ as d,c as e,a0 as o,o as r}from"./chunks/framework.B6JXc2q-.js";const p=JSON.parse('{"title":"2026-09-28 规则、文档、路由与死代码清理台账","description":"","frontmatter":{},"headers":[],"relativePath":"maintenance/2026-09-28-cleanup.md","filePath":"maintenance/2026-09-28-cleanup.md"}'),a={name:"maintenance/2026-09-28-cleanup.md"};function c(i,t,s,n,l,h){return r(),e("div",null,t[0]||(t[0]=[o('<h1 id="_2026-09-28-规则、文档、路由与死代码清理台账" tabindex="-1">2026-09-28 规则、文档、路由与死代码清理台账 <a class="header-anchor" href="#_2026-09-28-规则、文档、路由与死代码清理台账" aria-label="Permalink to &quot;2026-09-28 规则、文档、路由与死代码清理台账&quot;">​</a></h1><blockquote><p>类型：维护审计记录 范围：本轮被判定为疑似过时、重复、兼容或死代码的内容 基线：工作树开始时已有 WebUI 在线播放契约相关未提交修改；本轮不重置、不覆盖该批工作</p></blockquote><h2 id="_1-判断方法" tabindex="-1">1. 判断方法 <a class="header-anchor" href="#_1-判断方法" aria-label="Permalink to &quot;1. 判断方法&quot;">​</a></h2><p>内容只有满足下列证据之一才删除：</p><ol><li>生产装配和全仓库调用均不存在，且唯一测试只验证自身；</li><li>已被正式入口替代，当前 WebUI、内部调用和兼容契约均不再依赖；</li><li>文档描述的路由、字段、事件或生命周期从未落地，并与当前代码硬冲突；</li><li>文档已明确声明被当前权威规范取代；</li><li>依赖在配置与源码中均无引用。</li></ol><p>仅凭文件日期、名称包含 legacy/deprecated、或缺少静态 Python 调用，不足以删除。动态插件 action、框架注册入口和有明确兼容窗口的代码必须继续核对注册链、测试和版本策略。</p><h2 id="_2-已删除" tabindex="-1">2. 已删除 <a class="header-anchor" href="#_2-已删除" aria-label="Permalink to &quot;2. 已删除&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内容</th><th>处理</th><th>判断依据</th></tr></thead><tbody><tr><td><code>xiaomusic/api/routers/device.py</code></td><td>删除整个 router；移除 <code>/cmd</code>、<code>/cmdstatus</code>、<code>/device_list</code>、<code>/getvolume</code></td><td>WebUI 已脱离；正式设备控制已有 v1 接口；无生产调用；旧 <code>/cmd</code> 测试与实现冲突且清理前实测失败</td></tr><tr><td><code>DidCmd</code></td><td>从 API models 删除</td><td>只供已删除 <code>/cmd</code> 使用</td></tr><tr><td><code>xiaomusic/api/response_utils.py</code></td><td>删除</td><td>生产响应统一走 <code>api/response.py</code> 与 <code>routers/v1_shared.py</code>；该文件只被自身测试引用</td></tr><tr><td><code>ApiResponseBase</code>、<code>ApiPlaybackResponse</code></td><td>从 API models 删除</td><td>只供已删除 <code>response_utils.py</code> 使用</td></tr><tr><td><code>JSPluginManager.reset_restart_limit()</code>、<code>get_restart_status()</code>、<code>shutdown()</code></td><td>删除</td><td>全仓库无调用、无路由、无测试；内部重启逻辑不依赖这些外部表面方法</td></tr><tr><td><code>event-model.md</code>、<code>correlation-id.md</code>、<code>observability.md</code></td><td>删除未实施设计稿</td><td>标准事件、<code>play_id</code>、SSE <code>session_id</code>、event replay、snapshot 路由均不存在；ADR-0005 已改为 Withdrawn</td></tr><tr><td><code>module_inventory.md</code></td><td>删除重复清单</td><td>无入站引用；内容被 <code>system_overview.md</code> 和模块 README 覆盖</td></tr><tr><td>auth 五份历史阶段稿</td><td>删除</td><td>四份文档自身已声明被主规范取代；<code>auth_recovery_entrypoint_unification.md</code> 还依赖当前已不存在的方法和阶段模型；历史仍可从 Git 查询</td></tr><tr><td>docs 的 <code>axios</code>、<code>vite-plugin-vitepress-auto-sidebar</code></td><td>从 package 与 lock 删除</td><td>VitePress 配置已在历史提交删除；docs 源码无 import 或配置引用</td></tr><tr><td>对应自指测试</td><td>删除或改为生产装配断言</td><td>不再为已经删除的实现保留孤立测试</td></tr><tr><td><code>tests/unit/test_auth_self_heal.py</code></td><td>删除整套脱节测试</td><td>v1.1.6 发布说明已明确判定与现实现脱节；清理前 112 项中 90 项调用不存在的方法而失败，当前 auth 仍由 9 个其他测试文件、155 项用例覆盖</td></tr><tr><td>旧 docs / relay / transport 测试断言</td><td>改为当前入口与当前协议</td><td>移除对不存在 <code>docs/issues</code>、<code>docs/dev</code>、旧 auth 路径、旧 transport 签名和旧 site-media direct-first 策略的要求</td></tr></tbody></table><h2 id="_3-已修订而非删除" tabindex="-1">3. 已修订而非删除 <a class="header-anchor" href="#_3-已修订而非删除" aria-label="Permalink to &quot;3. 已修订而非删除&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内容</th><th>保留理由</th><th>本轮修订</th></tr></thead><tbody><tr><td><code>constraints.md</code></td><td>仍是所有边界的规则入口</td><td>删除未实现的全事件模型、全局 task owner 扫描、永久禁改文件和虚构 CI 门禁；每条现行规则补代码/测试依据</td></tr><tr><td><code>state-authority.md</code></td><td>状态 ownership 仍是核心约束</td><td>删除阶段编号与已过期偏差，改为当前 authority 表和 lifecycle 边界</td></tr><tr><td><code>playback_coordinator_interface.md</code></td><td>被 contributor guide、runtime 和 projection spec 引用，且对应真实 core 接口</td><td>删除旧 <code>context_*</code> 顶层字段和 title hash 规则，按当前 <code>PlaybackCoordinator</code> / Facade 边界重写</td></tr><tr><td>ADR-0005</td><td>ADR 历史本身不能抹掉</td><td>状态改为 Withdrawn，记录未实施证据与现行 EventBus 定位</td></tr><tr><td>auth 主规范与架构文档</td><td>atomic recovery 仍是当前权威</td><td>观测入口改为 <code>/api/admin/v1/auth/status</code> 与 <code>/api/internal/diagnostics/*</code>，旧 v1 路径明确为兼容入口</td></tr><tr><td><code>ARCHITECTURE.md</code></td><td>AI / 贡献者开工入口</td><td>删除旧 bug 清单、绝对禁改名单和四 source 描述，换成当前边界、五 source 和可证实维护状态</td></tr></tbody></table><h2 id="_4-调查后保留的兼容路由" tabindex="-1">4. 调查后保留的兼容路由 <a class="header-anchor" href="#_4-调查后保留的兼容路由" aria-label="Permalink to &quot;4. 调查后保留的兼容路由&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内容</th><th>为什么保留</th><th>直接依据</th><th>再评估条件</th></tr></thead><tbody><tr><td><code>/api/v1/sources*</code></td><td>v1.1.x 兼容入口</td><td><code>test_api_boundary_phase1.py</code> 检查旧新路径等价；管理页已迁到 <code>/api/admin/v1/sources*</code></td><td>明确主要版本移除窗口，并同步删等价性测试</td></tr><tr><td><code>/api/v1/auth/status</code></td><td>v1.1.x 兼容入口</td><td>与 <code>/api/admin/v1/auth/status</code> 共用 service；生产装配测试覆盖</td><td>同上</td></tr><tr><td><code>/api/v1/debug/*</code></td><td>v1.1.x 诊断兼容入口</td><td>与 <code>/api/internal/diagnostics/*</code> 共用 service；等价性测试覆盖</td><td>运维调用迁移完成并确定移除版本</td></tr><tr><td>music / playlist legacy 读取与 identity 兼容路由</td><td>旧客户端与 identity 迁移仍有保护</td><td>identity 兼容测试、plugin service 和旧协议路径仍在</td><td>调用方清单和替代 API 完整后单独清理</td></tr></tbody></table><p>这些路由虽然不属于 Public API 白名单，但当前仍有明确兼容价值；本轮不把“deprecated”误判为“dead”。</p><h2 id="_5-调查后保留的代码" tabindex="-1">5. 调查后保留的代码 <a class="header-anchor" href="#_5-调查后保留的代码" aria-label="Permalink to &quot;5. 调查后保留的代码&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内容</th><th>为什么保留</th><th>判断依据</th></tr></thead><tbody><tr><td>五个内置 SourcePlugin</td><td>正式播放链组成部分</td><td>default registry 注册，Coordinator 动态选择，测试覆盖</td></tr><tr><td><code>LegacyPayloadSourcePlugin</code> 与 <code>LEGACY_HINT_MAP</code></td><td>有明确迁移语义和 v1.2 再评估说明</td><td>adapter / registry 注释及兼容测试；当前版本仍为 1.1.7</td></tr><tr><td><code>xiaomusic/online_music.py</code>、<code>xiaomusic/js_plugin_manager.py</code></td><td>兼容导出仍受调用和 identity 测试保护</td><td>runtime import 与 <code>test_module_split_compat.py</code></td></tr><tr><td>JS manager 中 MusicFree action 方法</td><td>Node runner 通过字符串动态分派</td><td><code>js_plugin_runner.js</code> action 表；不能按 Python 静态引用删除</td></tr><tr><td><code>file_watcher.py</code></td><td>生产 runtime 实际创建并启动</td><td><code>xiaomusic/xiaomusic.py</code> 的 <code>FileWatcherManager</code> 调用链</td></tr><tr><td>WebUI service exports</td><td>页面或测试仍有调用</td><td>HomePage、SourcesPage、DiagnosticsPage、AuthStatusCard 与 service tests</td></tr></tbody></table><h2 id="_6-保留的文档类别" tabindex="-1">6. 保留的文档类别 <a class="header-anchor" href="#_6-保留的文档类别" aria-label="Permalink to &quot;6. 保留的文档类别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>为什么保留</th><th>判断依据</th></tr></thead><tbody><tr><td>API v1 spec</td><td>Public API 最终权威</td><td>25 项白名单与生产装配测试</td></tr><tr><td>runtime / player state / SSE / WebUI / auth 主规范</td><td>定义当前运行行为</td><td>对应代码入口和定点测试</td></tr><tr><td>system overview、source/webui/auth/runtime architecture</td><td>定义当前模块边界</td><td>被开工入口和 contributor guide 引用，内容可映射到现有目录</td></tr><tr><td>ADR-0001~0004、0006</td><td>当前仍有效的决策历史</td><td>状态为 Accepted，约束在代码或测试中有落点</td></tr><tr><td>release notes 与 CHANGELOG</td><td>版本历史，不以旧日期判死</td><td>发布记录需要可追溯；其中历史文件名不等于现行规范入口</td></tr><tr><td><code>webui_playback_contract_incident_and_repair_plan.md</code></td><td>当前工作尚未完成实机闭环</td><td>设备实播仍受认证阻断，根 README 与 architecture index 引用</td></tr></tbody></table><h2 id="_7-有意不清理的本地目录" tabindex="-1">7. 有意不清理的本地目录 <a class="header-anchor" href="#_7-有意不清理的本地目录" aria-label="Permalink to &quot;7. 有意不清理的本地目录&quot;">​</a></h2><p><code>.local/</code> 包含当前在线播放契约工作的部署包、worktree、回滚和验收材料。它虽被 Git 忽略，但属于正在进行工作的恢复证据，本轮不碰。</p><p><code>.opencode/</code> 可能属于本地工具状态，也不以体积或忽略状态直接判为垃圾。</p><p>已删除可重建的 <code>node_modules</code>、VitePress / WebUI 构建输出、pytest / Ruff cache、Python bytecode 与旧 <code>monitor_run.log</code>；这些内容不属于项目事实源。</p><h2 id="_8-验证记录" tabindex="-1">8. 验证记录 <a class="header-anchor" href="#_8-验证记录" aria-label="Permalink to &quot;8. 验证记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>门禁</th><th>结果</th></tr></thead><tbody><tr><td>后端定点测试</td><td>29 passed；随后清理后的专项回归 23 passed</td></tr><tr><td>全量 Python</td><td><strong>1194 passed, 2 skipped, 0 failed</strong>；仅剩本机 requests 依赖版本 warning</td></tr><tr><td>本轮修改 Python 文件 Ruff</td><td>通过</td></tr><tr><td>WebUI Vitest</td><td><strong>12 files / 52 tests passed</strong></td></tr><tr><td>WebUI production build</td><td>通过；仅保留既有 Material Icons 运行时路径提示</td></tr><tr><td>Node 安全测试</td><td><strong>11 passed</strong></td></tr><tr><td>docs 干净安装</td><td>删除 docs <code>node_modules</code> 后执行 <code>npm ci --ignore-scripts</code> 成功，126 packages</td></tr><tr><td>VitePress build</td><td>通过</td></tr><tr><td>Markdown 相对链接</td><td>46 个项目 Markdown 文件检查通过</td></tr><tr><td>生产路由装配</td><td>119 个注册路径；四个已删除 device 路由均不存在</td></tr><tr><td>残留引用扫描</td><td>删除的代码符号、auth 阶段文档和 router 注册无活动引用；仅 ADR/constraints 保留“未实施设计不存在”的历史说明</td></tr><tr><td><code>git diff --check</code></td><td>通过</td></tr></tbody></table><p>全仓库 Ruff 仍有本轮范围外的历史格式与旧式类型标注问题；本轮未用批量 <code>--fix</code> 扩大改动边界。功能与测试门禁已经全绿。</p>',24)]))}const b=d(a,[["render",c]]);export{p as __pageData,b as default};
